The RIS-RRT algorithm is a popular motion planning method used in robotics and computer science. Here's a simplified pseudocode representation of the algorithm, including reflection:

```
Function RIS-RRT(Q, q_goal, obstacle_func, step_size)
    // Initialize the tree with a random configuration
    T <- LeafNode(Q, q0)
    while not goal_test(q_goal, q0)
        // Sample a new configuration
        q_sample <- sample_configuration(Q, step_size)

        // Check if the new configuration collides with the obstacles
        if collides(obstacle_func, q_sample)
            // Apply reflection if the collision
            q_reflected <- reflect(q_sample, obstacle_func)
            // Check if the reflected configuration is closer to the goal
            if distance(q_goal, q_reflected) < distance(q_goal, q0)
                // Update the tree with the reflected configuration
                T <- extend_tree(T, q_reflected)
            end if
        else
            // Expand the tree with the new configuration
            T <- extend_tree(T, q_sample)
        end if

        // Perform RIS (Rapidly-exploring Random Tree) planning
        if extended_distance(T) > distance(q_goal, q0)
            // Select the nearest neighbor to the goal
            q_nearest <- nearest_neighbor(T, q_goal)
            // Move the tree towards the goal
            T <- move_tree(T, q_nearest, step_size)
        end if

    end while
    return T
end Function

Function extend_tree(T, q_new)
    // Add the new configuration to the tree
    T.insert(q_new)
    // Find the nearest neighbor to the new configuration
    q_nearest <- nearest_neighbor(T, q_new)
    // Compute the steering vector
    v <- steer(q_new, q_nearest)
    // Add the child nodes to the tree
    for i in range(num_samples)
        q_child <- q_new + v * step_size
        T.insert(q_child)
    end for
    return T
end Function

Function reflect(q_sample, obstacle_func)
    // Compute the reflection direction
    v <- (q_sample - obstacle_center) / distance(q_sample, obstacle_center)
    // Compute the reflected configuration
    q_reflected <- q_sample - 2 * v * dot(q_sample - obstacle_center, v)
    return q_reflected
end Function

Function nearest_neighbor(T, q_goal)
    // Find the configuration in the tree that is closest to the goal
    q_nearest <- argmin_distance(q_goal, T)
    return q_nearest
end Function

Function move_tree(T, q_nearest, step_size)
    // Move the tree towards the goal
    for i in range(num_steps)
        q_move <- q_nearest + (q_goal - q_nearest) * step_size
        T.insert(q_move)
        q_nearest <- q_move
    end for
    return T
end Function
```

