```csharp
using System;
using System.Net;
using System.IO;

class HelloWorldHttpListener
{
    static void Main(string[] args)
    {
        HttpListener listener = new HttpListener();
        listener.Prefixes.Add("http://localhost:8080/");

        listener.Start();

        Console.WriteLine("Serveur HTTP démarré. Appuyez sur Entrée pour arrêter.");

        while (Console.ReadLine() == "")
        {
            HttpListenerContext context = listener.GetContext();
            HttpListenerRequest request = context.Request;

            if (request.Url.AbsolutePath == "/")
            {
                SendHelloWorldResponse(context);
            }
            else
            {
                SendErrorResponse(context, "Page not found");
            }
        }

        listener.Stop();
    }

    static void SendHelloWorldResponse(HttpListenerContext context)
    {
        String responseString = @"<html><body>Hello, World!</body></html>";
        context.Response.ContentType = "text/html";
        context.Response.ContentLength64 = responseString.Length;
        Stream output = context.Response.OutputStream;
        byte[] buffer = System.Text.Encoding.UTF8.GetBytes(responseString);
        output.Write(buffer, 0, buffer.Length);
        output.Close();
    }

    static void SendErrorResponse(HttpListenerContext context, string errorMessage)
    {
        String responseString = @"<html><body>Error: " + errorMessage + "</body></html>";
        context.Response.ContentType = "text/html";
        context.Response.ContentLength64 = responseString.Length;
        Stream output = context.Response.OutputStream;
        byte[] buffer = System.Text.Encoding.UTF8.GetBytes(responseString);
        output.Write(buffer, 0, buffer.Length);
        output.Close();
    }
}
