  // Calculate the difference in X and Y coordinates
  var dx = targetX - currX;
  var dy = targetY - currY;

  // Calculate the absolute value of the differences
  var dxa = mAbs(dx);
  var dva = mAbs(dy);

  // Determine the direction of movement based on the current direction
  var moveDir = currDir;
  if (currDir === 'U') {
    moveDir = (dy > 0) ? 'D' : 'U';
  } else if (currDir === 'D') {
    moveDir = (dy < 0) ? 'U' : 'D';
  } else if (currDir === 'R') {
    moveDir = (dx > 0) ? 'L' : 'R';
  } else if (currDir === 'L') {
    moveDir = (dx < 0) ? 'R' : 'L';
  }

  // Calculate the number of steps needed to reach the target
  var stepsX = Math.floor(dxa / mFloor(mSign(dx)));
  var stepsY = Math.floor(dva / mFloor(mSign(dy)));

  // Calculate the remaining distance
  var remainingDX = dx % mFloor(mSign(dx));
  var remainingDY = dy % mFloor(mSign(dy));

  // Move in the correct direction
