    if (moveDir === 'U' || moveDir === 'D') {
      TurnLike(moveDir, NAME_1);
    } else {
      MoveLike(NAME_1);
    }
  }

  // Turn to face the correct direction
  if (remainingDX !== 0) {
    if (moveDir === 'L' && dx < 0) {
      TurnLike('R', NAME_1);
    } else if (moveDir === 'R' && dx > 0) {
      TurnLike('L', NAME_1);
    }
  }

  if (remainingDY !== 0) {
    if (moveDir === 'U' && dy < 0) {
      TurnLike('D', NAME_1);
    } else if (moveDir === 'D' && dy > 0) {
      TurnLike('U', NAME_1);
    }
  }
}
```
